// Auto-generated from the Visual Audit Playbook doc. Rendered natively in PlaybookView.
export const VISUAL_AUDIT_CSS = ".pbdoc{\n  --navy:#111214; --navy2:#1D2024; --deep:#111214; --ink:#1A1A1A;\n  --blue:#B8460F; --blue2:#FF9A5C; --bluesoft:#FFF1E8; --blueline:#F5CBAE;\n  --amber:#111214; --ambersoft:#F3EFE8; --amberline:#E0D9CC;\n  --paper:#F6F4EF; --card:#FFFFFF; --border:#E6E2DA; --muted:#4A4D52; --muted2:#85878C;\n}\n.pbdoc *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}\n.pbdoc{margin:0;font-family:'Inter',-apple-system,system-ui,sans-serif;background:var(--paper);\n  color:var(--ink);font-size:17px;line-height:1.62;-webkit-text-size-adjust:100%;}\n.pbdoc .wrap{max-width:680px;margin:0 auto;}\n.pbdoc h1, .pbdoc h2, .pbdoc h3, .pbdoc h4{font-family:'Inter',sans-serif;color:var(--navy);margin:0;line-height:1.18;letter-spacing:-0.01em;}\n.pbdoc p{margin:0 0 13px;}\n.pbdoc b, .pbdoc strong{font-weight:650;color:var(--ink);}\n.pbdoc a{color:var(--blue);text-decoration:none;}\n.pbdoc em{font-style:italic;}\n.pbdoc ul{margin:6px 0 14px;padding:0;list-style:none;}\n.pbdoc li{position:relative;padding-left:22px;margin:0 0 9px;}\n.pbdoc li::before{content:\"\";position:absolute;left:3px;top:10px;width:6px;height:6px;border-radius:50%;background:var(--blue);}\n.pbdoc .topbar{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.94);backdrop-filter:blur(8px);\n  display:flex;align-items:center;justify-content:space-between;padding:12px 18px;\n  border-bottom:1px solid var(--border);}\n.pbdoc .topbar .bx{display:flex;align-items:center;gap:9px;}\n.pbdoc .topbar .nm{font-family:'Inter';font-weight:600;color:#111214;font-size:15px;letter-spacing:.01em;}\n.pbdoc .topbar .nm .lt{font-weight:300;color:#B8460F;}\n.pbdoc .topbar a.toc{font-family:'Inter';font-weight:600;font-size:13px;color:#B8460F;\n  border:1px solid var(--blueline);padding:6px 13px;border-radius:20px;}\n.pbdoc .mark-blue, .pbdoc .mark-white{display:inline-flex;align-items:center;}\n.pbdoc .mark-white{display:none;}\n.pbdoc[data-theme=\"dark\"] .mark-blue{display:none;}\n.pbdoc[data-theme=\"dark\"] .mark-white{display:inline-flex;}\n.pbdoc[data-theme=\"dark\"] .topbar{background:rgba(17,18,20,.97);border-bottom-color:rgba(255,255,255,.08);}\n.pbdoc[data-theme=\"dark\"] .topbar .nm{color:#F2EFE9;}\n.pbdoc[data-theme=\"dark\"] .topbar .nm .lt{color:#FF6B1A;}\n.pbdoc[data-theme=\"dark\"] .topbar a.toc{color:#FF9A5C;border-color:rgba(255,154,92,.42);}\n.pbdoc .hero{background:linear-gradient(180deg,#FFF1E8 0%,#FAF7F2 55%,#FFFFFF 100%);\n  color:#111214;padding:40px 22px 34px;border-bottom:1px solid var(--border);}\n.pbdoc .hero .eyebrow{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.2em;\n  text-transform:uppercase;color:#B8460F;margin-bottom:14px;}\n.pbdoc .hero h1{color:#111214;font-size:34px;font-weight:700;line-height:1.05;letter-spacing:-0.015em;}\n.pbdoc .hero h1 .b{color:#B8460F;}\n.pbdoc .hero .bar{width:54px;height:3px;background:#B8460F;border-radius:3px;margin:20px 0 16px;}\n.pbdoc .hero p{color:#4A4D52;font-size:16px;margin:0;}\n.pbdoc .hero .meta{margin-top:20px;display:flex;gap:10px;flex-wrap:wrap;}\n.pbdoc .hero .pill{font-family:'Inter';font-weight:600;font-size:11px;letter-spacing:.08em;text-transform:uppercase;\n  color:#B8460F;border:1px solid var(--blueline);border-radius:20px;padding:5px 12px;background:rgba(255,255,255,.6);}\n.pbdoc[data-theme=\"dark\"] .hero{background:radial-gradient(130% 100% at 80% 0%,#3A2210 0%,#111214 46%,#111214 100%);\n  color:#fff;border-bottom:none;}\n.pbdoc[data-theme=\"dark\"] .hero .eyebrow{color:#FF9A5C;}\n.pbdoc[data-theme=\"dark\"] .hero h1{color:#fff;}\n.pbdoc[data-theme=\"dark\"] .hero h1 .b{color:#FF9A5C;}\n.pbdoc[data-theme=\"dark\"] .hero .bar{background:#FF9A5C;}\n.pbdoc[data-theme=\"dark\"] .hero p{color:#B5B2AC;}\n.pbdoc[data-theme=\"dark\"] .hero .pill{color:#FF9A5C;border-color:rgba(255,154,92,.4);background:transparent;}\n.pbdoc .pad{padding:0 22px;}\n.pbdoc .toc{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:8px 6px;margin:22px 0 6px;}\n.pbdoc .toc a{display:flex;align-items:center;gap:14px;padding:12px 14px;border-bottom:1px solid var(--border);}\n.pbdoc .toc a:last-child{border-bottom:none;}\n.pbdoc .toc .n{font-family:'Inter';font-weight:700;color:var(--blue);font-size:15px;width:26px;flex:none;}\n.pbdoc .toc .t{font-family:'Inter';font-weight:600;color:var(--navy);font-size:16px;line-height:1.2;}\n.pbdoc .toc .s{font-size:13px;color:var(--muted);margin-top:1px;}\n.pbdoc section{padding:34px 22px 10px;scroll-margin-top:64px;}\n.pbdoc section + section{border-top:10px solid #EFEBE3;}\n.pbdoc .kick{display:inline-flex;align-items:center;gap:9px;font-family:'Inter';font-weight:600;font-size:12px;\n  letter-spacing:.15em;text-transform:uppercase;color:var(--blue);margin-bottom:11px;}\n.pbdoc .kick .num{font-family:'Inter';font-weight:700;color:var(--navy);}\n.pbdoc .kick::before{content:\"\";width:22px;height:2px;background:var(--blue);border-radius:2px;}\n.pbdoc section > h2{font-size:26px;font-weight:600;margin-bottom:10px;}\n.pbdoc .sub{color:var(--muted);font-size:16px;margin-bottom:20px;}\n.pbdoc h3.blk{font-size:19px;font-weight:600;margin:22px 0 9px;}\n.pbdoc h4.mini{font-family:'Inter';font-weight:600;font-size:16px;color:var(--navy);margin:16px 0 5px;}\n.pbdoc .card{background:var(--card);border:1px solid var(--border);border-radius:15px;padding:17px 18px;margin:0 0 14px;}\n.pbdoc .card h4{font-family:'Inter';font-weight:600;font-size:17px;color:var(--navy);margin:0 0 6px;}\n.pbdoc .card p{margin:0;font-size:15.5px;color:var(--ink);}\n.pbdoc .card ul{margin:8px 0 0;}\n.pbdoc .card li{font-size:15.5px;}\n.pbdoc .eyebrow{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.12em;text-transform:uppercase;\n  color:var(--blue);margin-bottom:8px;}\n.pbdoc .tint{background:var(--bluesoft);border:1px solid var(--blueline);border-radius:15px;padding:17px 18px;margin:0 0 14px;}\n.pbdoc .tint p{margin:0;font-size:15.5px;}\n.pbdoc .soft{background:#F1EDE5;border:1px solid var(--border);border-radius:15px;padding:17px 18px;margin:0 0 14px;}\n.pbdoc .tip{background:var(--ambersoft);border:1px solid var(--amberline);border-radius:15px;padding:16px 18px;margin:0 0 14px;}\n.pbdoc .tip .lbl{font-family:'Inter';font-weight:700;font-size:12px;letter-spacing:.1em;text-transform:uppercase;\n  color:var(--amber);margin-bottom:5px;}\n.pbdoc .tip p{margin:0;font-size:15.5px;}\n.pbdoc .big{font-family:'Inter';font-weight:500;font-size:18px;color:var(--navy);line-height:1.4;margin:0;}\n.pbdoc .stats{display:flex;gap:11px;margin:4px 0 16px;}\n.pbdoc .stats .s{flex:1;background:var(--card);border:1px solid var(--border);border-radius:14px;padding:15px 8px;text-align:center;}\n.pbdoc .stats .v{font-family:'Inter';font-weight:700;font-size:26px;color:var(--blue);line-height:1;}\n.pbdoc .stats .l{font-size:12px;color:var(--muted);margin-top:6px;line-height:1.3;}\n.pbdoc .script{background:var(--card);border:1px solid var(--border);border-left:4px solid var(--blue);\n  border-radius:13px;padding:15px 17px;margin:0 0 13px;}\n.pbdoc .script .chip{display:inline-block;background:var(--navy);color:#fff;font-family:'Inter';font-weight:600;\n  font-size:12.5px;letter-spacing:.02em;padding:4px 12px;border-radius:20px;margin-bottom:9px;}\n.pbdoc .script .when{font-size:14px;color:var(--muted);margin-bottom:9px;}\n.pbdoc .script .when b{color:var(--navy);}\n.pbdoc .script .say{font-size:15.5px;line-height:1.55;}\n.pbdoc .script .say em{color:var(--blue);font-style:normal;font-weight:600;}\n.pbdoc .step{display:flex;gap:13px;margin:0 0 14px;}\n.pbdoc .step .n{flex:none;width:32px;height:32px;border-radius:9px;background:var(--navy);color:#fff;\n  font-family:'Inter';font-weight:600;font-size:16px;display:flex;align-items:center;justify-content:center;}\n.pbdoc .step .n.blue{background:var(--blue);}\n.pbdoc .step .t{font-family:'Inter';font-weight:600;font-size:16.5px;color:var(--navy);margin-bottom:2px;}\n.pbdoc .step p{margin:0;font-size:15px;color:var(--muted);}\n.pbdoc .drow{background:var(--card);border:1px solid var(--border);border-radius:13px;padding:14px 16px;margin:0 0 11px;}\n.pbdoc .drow .top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:4px;}\n.pbdoc .drow .nm{font-family:'Inter';font-weight:600;font-size:16px;color:var(--navy);}\n.pbdoc .drow .wt{font-family:'Inter';font-weight:700;font-size:15px;color:var(--blue);flex:none;}\n.pbdoc .drow .wt.neg{color:#C0392B;}\n.pbdoc .drow p{margin:0;font-size:14.5px;color:var(--muted);}\n.pbdoc .badge{display:inline-block;font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.03em;\n  padding:3px 10px;border-radius:20px;background:var(--bluesoft);color:var(--blue);border:1px solid var(--blueline);}\n.pbdoc .badge.navy{background:var(--navy);color:#fff;border-color:var(--navy);}\n.pbdoc .chk{display:flex;align-items:flex-start;gap:12px;padding:11px 0;border-bottom:1px dashed #E0D9CC;}\n.pbdoc .chk .box{flex:none;width:20px;height:20px;border:2px solid var(--blue);border-radius:5px;margin-top:1px;}\n.pbdoc .chk .tx{font-size:15.5px;}\n.pbdoc .chk .tx b{color:var(--navy);}\n.pbdoc .grouplbl{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.12em;text-transform:uppercase;\n  color:var(--blue);margin:18px 0 4px;}\n.pbdoc .phase{background:var(--card);border:1px solid var(--border);border-left:4px solid var(--blue);\n  border-radius:14px;padding:16px 18px;margin:0 0 14px;}\n.pbdoc .phase .ph{display:flex;align-items:center;gap:10px;margin-bottom:8px;}\n.pbdoc .phase .lab{font-family:'Inter';font-weight:600;font-size:12px;letter-spacing:.04em;text-transform:uppercase;\n  background:var(--navy);color:#fff;padding:4px 11px;border-radius:20px;}\n.pbdoc .phase h4{font-family:'Inter';font-weight:600;font-size:17px;color:var(--navy);margin:0;}\n.pbdoc .phase .g{color:var(--muted);font-size:14.5px;margin:0 0 8px;}\n.pbdoc .phase li{font-size:15px;margin-bottom:6px;}\n.pbdoc .beat{display:flex;gap:12px;align-items:flex-start;background:var(--card);border:1px solid var(--border);\n  border-radius:13px;padding:13px 15px;margin:0 0 10px;}\n.pbdoc .beat .tm{flex:none;}\n.pbdoc .beat h4{font-size:16px;margin:6px 0 2px;}\n.pbdoc .beat p{margin:0;font-size:14.5px;color:var(--muted);}\n.pbdoc .foot{background:var(--deep);color:#A7A9AD;text-align:center;padding:30px 22px 34px;margin-top:20px;}\n.pbdoc .foot .big{color:#F2EFE9;font-family:'Inter';font-weight:500;font-size:17px;line-height:1.45;max-width:520px;margin:0 auto 16px;}\n.pbdoc .foot .sm{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:#85878C;font-family:'Inter';}\n.pbdoc .totop{display:inline-block;margin-top:14px;font-family:'Inter';font-weight:600;font-size:13px;color:#FF9A5C;\n  border:1px solid rgba(140,135,125,.4);padding:8px 16px;border-radius:20px;}\n.pbdoc .two{display:grid;grid-template-columns:1fr;gap:0;}\n.pbdoc .tbtn{display:inline-flex;align-items:center;justify-content:center;width:36px;height:33px;\n  border:1px solid rgba(140,135,125,.4);border-radius:20px;background:transparent;cursor:pointer;\n  font-size:15px;line-height:1;padding:0;margin-right:9px;}\n.pbdoc .topbar .right{display:flex;align-items:center;}\n.pbdoc .chk{cursor:pointer;user-select:none;-webkit-user-select:none;}\n.pbdoc .chk .box{transition:background .12s,border-color .12s;position:relative;}\n.pbdoc .chk.on .box{background:var(--blue);border-color:var(--blue);}\n.pbdoc .chk.on .box::after{content:\"\";position:absolute;left:5px;top:1px;width:5px;height:10px;\n  border:solid #fff;border-width:0 2.5px 2.5px 0;transform:rotate(45deg);}\n.pbdoc .chk.on .tx{color:var(--muted2);text-decoration:line-through;text-decoration-color:rgba(110,113,119,.55);}\n.pbdoc .chk.on .tx b{color:var(--muted2);}\n.pbdoc .chkbar{display:flex;justify-content:flex-end;margin-bottom:6px;}\n.pbdoc .chkbar button{font-family:'Inter';font-weight:600;font-size:13px;color:var(--blue);background:transparent;\n  border:1px solid var(--blueline);border-radius:20px;padding:7px 15px;cursor:pointer;}\n.pbdoc[data-theme=\"dark\"]{\n  --paper:#111214; --card:#1A1C1F; --ink:#E8E5DF; --muted:#A7A9AD; --muted2:#7D8086;\n  --border:#2A2D31; --navy:#33363B; --blue:#FF9A5C; --bluesoft:rgba(255,107,26,.12); --blueline:rgba(255,154,92,.34);\n  --amber:#FF9A5C; --ambersoft:rgba(255,255,255,.05); --amberline:rgba(255,154,92,.34);\n}\n.pbdoc[data-theme=\"dark\"] h1, .pbdoc[data-theme=\"dark\"] h2, .pbdoc[data-theme=\"dark\"] h3, .pbdoc[data-theme=\"dark\"] h4, .pbdoc[data-theme=\"dark\"] .toc .t, .pbdoc[data-theme=\"dark\"] .kick .num, .pbdoc[data-theme=\"dark\"] .card h4, .pbdoc[data-theme=\"dark\"] h4.mini, .pbdoc[data-theme=\"dark\"] .big, .pbdoc[data-theme=\"dark\"] .script .when b, .pbdoc[data-theme=\"dark\"] .step .t, .pbdoc[data-theme=\"dark\"] .drow .nm, .pbdoc[data-theme=\"dark\"] .chk .tx b, .pbdoc[data-theme=\"dark\"] .phase h4{color:#F2EFE9;}\n.pbdoc[data-theme=\"dark\"] .soft{background:#1D2024;}\n.pbdoc[data-theme=\"dark\"] section + section{border-top-color:#0B0C0D;}\n.pbdoc[data-theme=\"dark\"] .chk{border-bottom-color:#2A2D31;}\n.pbdoc[data-theme=\"dark\"] .drow .wt.neg{color:#FF7A7A;}\n.pbdoc[data-theme=\"dark\"] .tbtn, .pbdoc[data-theme=\"dark\"] .topbar a.toc{border-color:rgba(255,255,255,.16);}\n.pbdoc .shotcard{background:#F6F4EF;border:1px solid var(--border);border-radius:14px;padding:14px;margin:0 0 13px;}\n.pbdoc .shotcard .browser{background:#fff;border:1px solid var(--border);border-radius:10px;overflow:hidden;}\n.pbdoc .shotcard .bar{background:#EFEBE3;padding:7px 10px;display:flex;gap:5px;align-items:center;border-bottom:1px solid var(--border);}\n.pbdoc .shotcard .bar span{width:8px;height:8px;border-radius:50%;background:#D9D4CA;display:inline-block;}\n.pbdoc .shotcard .body{padding:16px 14px;position:relative;font-size:13px;color:var(--muted);}\n.pbdoc .shotcard .anno{position:relative;display:inline-block;}\n.pbdoc .shotcard .circle{position:absolute;border:2.5px solid #E0454A;border-radius:50%;}\n.pbdoc .shotcard .arrow{position:absolute;color:#E0454A;font-family:'Grotesk';font-weight:700;font-size:13px;}\n.pbdoc .shotcard .cap{display:inline-block;background:#E0454A;color:#fff;font-family:'Inter';font-weight:600;font-size:11.5px;\n  padding:3px 9px;border-radius:6px;margin-top:8px;}\n.pbdoc .callscript{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:15px 17px;margin:0 0 12px;}\n.pbdoc .callscript .cs-n{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;border-radius:7px;\n  background:var(--navy);color:#fff;font-family:'Inter';font-weight:700;font-size:13px;flex:none;}\n.pbdoc .callscript .cs-row{display:flex;gap:11px;margin-bottom:11px;align-items:flex-start;}\n.pbdoc .callscript .cs-row:last-child{margin-bottom:0;}\n.pbdoc .callscript .cs-t{font-family:'Inter';font-weight:600;font-size:15px;color:var(--navy);margin-bottom:2px;}\n.pbdoc .callscript .cs-row p{margin:0;font-size:14.5px;color:var(--ink);}\n.pbdoc[data-theme=\"dark\"] .shotcard{background:#1D2024;border-color:#2A2D31;}\n.pbdoc[data-theme=\"dark\"] .shotcard .browser{background:#17191C;border-color:#2A2D31;}\n.pbdoc[data-theme=\"dark\"] .shotcard .bar{background:#1A1C1F;border-color:#2A2D31;}\n/* Primed & Booked: contrast on orange fills in dark mode */\n.pbdoc[data-theme=\"dark\"] .step .n.blue{color:#111214;}\n.pbdoc[data-theme=\"dark\"] .chk.on .box::after{border-color:#111214;}\n";

export const VISUAL_AUDIT_HTML = "<div class=\"wrap\">\n<div id=\"contents\" style=\"scroll-margin-top:64px;padding-top:26px;\" class=\"pad\">\n  <div class=\"kick\">&nbsp;Contents</div><h2 style=\"font-family:'Inter';font-size:24px;\">What's inside</h2>\n</div>\n<div class=\"pad\"><div class=\"toc\"><a href=\"#why\"><span class=\"n\">01</span><span><span class=\"t\">Why this works</span><div class=\"s\">A calmer way to open the same doors</div></span></a><a href=\"#tools\"><span class=\"n\">02</span><span><span class=\"t\">Tools & setup</span><div class=\"s\">Screenshot, markup, and a repeatable style</div></span></a><a href=\"#workflow\"><span class=\"n\">03</span><span><span class=\"t\">The workflow</span><div class=\"s\">Seven steps from prospect to sent</div></span></a><a href=\"#anatomy\"><span class=\"n\">04</span><span><span class=\"t\">Anatomy of a visual audit</span><div class=\"s\">The four-part structure that gets replies</div></span></a><a href=\"#scripts\"><span class=\"n\">05</span><span><span class=\"t\">The script library</span><div class=\"s\">13 scenarios, screenshot + message for each</div></span></a><a href=\"#channels\"><span class=\"n\">06</span><span><span class=\"t\">Channel templates</span><div class=\"s\">Email, Messenger, DM, and SMS versions</div></span></a><a href=\"#bridge\"><span class=\"n\">07</span><span><span class=\"t\">Bridging to the call</span><div class=\"s\">Turning a reply into a booked time</div></span></a><a href=\"#oncall\"><span class=\"n\">08</span><span><span class=\"t\">On the call</span><div class=\"s\">A low-pressure structure, so it's never a blank page</div></span></a><a href=\"#followup\"><span class=\"n\">09</span><span><span class=\"t\">Follow-up sequence</span><div class=\"s\">The 30-day cadence, adapted for this method</div></span></a><a href=\"#objections\"><span class=\"n\">10</span><span><span class=\"t\">Objection handling</span><div class=\"s\">What's different in writing, plus the same eight</div></span></a><a href=\"#checklist\"><span class=\"n\">11</span><span><span class=\"t\">Daily checklist</span><div class=\"s\">Print it. Run it. No camera required.</div></span></a><a href=\"#combine\"><span class=\"n\">12</span><span><span class=\"t\">Combining both methods</span><div class=\"s\">When to use this vs. the video</div></span></a></div></div>\n<section id=\"why\">\n      <div class=\"kick\"><span class=\"num\">Section 01</span>&nbsp;Why this works</div>\n      <h2>Why this works</h2><p class=\"sub\">A calmer way to open the same doors</p>\n<div class=\"stats\">\n  <div class=\"s\"><div class=\"v\">0</div><div class=\"l\">takes, no recording, no re-dos</div></div>\n  <div class=\"s\"><div class=\"v\">2min</div><div class=\"l\">to put together, start to send</div></div>\n  <div class=\"s\"><div class=\"v\">100%</div><div class=\"l\">reviewable before it ever goes out</div></div>\n</div>\n<h4 class=\"mini\">It does the same job as the video</h4>\n<p>The personalized video works because it proves you actually looked at their business and found something real. A marked-up screenshot proves the exact same thing — a circle on the one broken button says \"I looked\" just as clearly as saying it out loud.</p>\n<h4 class=\"mini\">You can make it exactly right before it goes anywhere</h4>\n<p>There's no take to mess up. You write it, read it back, fix a word, and send it when it's actually ready — not when you finally got through a recording without stumbling.</p>\n<h4 class=\"mini\">Some prospects prefer it anyway</h4>\n<p>A busy owner can skim an image and two sentences in five seconds. Not everyone wants to commit to pressing play on a stranger's video — this meets them where they already are.</p>\n<div class=\"tint\"><div class=\"eyebrow\">The honest reframe</div>\n<p>This isn't the backup plan. It's a fully legitimate outreach method on its own — plenty of agencies run their entire outreach this way. Pick it because it's sustainable for you, not because it's second-best.</p></div>\n<div class=\"soft\"><div class=\"eyebrow\">The one-line philosophy</div>\n<p class=\"big\">Show them the one thing that's costing them jobs. Say it plainly. Point to how it works. Let them come to you.</p></div>\n</section><section id=\"tools\">\n      <div class=\"kick\"><span class=\"num\">Section 02</span>&nbsp;Setup</div>\n      <h2>Tools & setup</h2><p class=\"sub\">Screenshot, markup, and a repeatable style</p>\n<div class=\"card\"><h4>📸 Taking the screenshot</h4>\n<ul style=\"margin-top:2px;\"><li><b>Mac:</b> Cmd+Shift+4, then drag over just the leak — not the whole page</li>\n<li><b>Windows:</b> Win+Shift+S (Snipping Tool) — same idea, crop tight</li>\n<li><b>Phone:</b> Power + Volume Down, then crop in your Photos app</li></ul></div>\n<div class=\"card\"><h4>🖊️ Marking it up</h4>\n<p style=\"margin-bottom:8px;\"><b>Markup Hero</b> (free, browser-based) is the recommended default — drag in your screenshot, drop a circle or arrow, add a short text caption, done.</p>\n<ul style=\"margin:0;\"><li><b>Alternatives:</b> Skitch, or the built-in markup in Mac Preview / Windows Photos</li><li>All do the same job — pick whichever is already on your machine</li></ul></div>\n<div class=\"tip\"><div class=\"lbl\">One style, every time</div>\n<p>Pick one color (red works well against most websites) and stick to it: one circle or arrow, one short caption in plain words. Consistency makes your outreach recognizable and keeps you fast — no redesigning the markup each time.</p></div>\n<div class=\"card\"><h4>🗂️ Keep it organized</h4>\n<p style=\"margin:0;\">One folder, named by date, for the marked-up screenshots you send each day. If a prospect replies a week later, you can find exactly what you sent them in seconds.</p></div>\n</section><section id=\"workflow\">\n      <div class=\"kick\"><span class=\"num\">Section 03</span>&nbsp;Execution</div>\n      <h2>The workflow</h2><p class=\"sub\">Seven steps from prospect to sent</p>\n<div class=\"step\"><div class=\"n blue\">1</div><div><div class=\"t\">Find & qualify the prospect</div><p>Same scorecard as always — the one leak, reachable, owner-led, means to pay.</p></div></div><div class=\"step\"><div class=\"n blue\">2</div><div><div class=\"t\">Open their site, find the one leak</div><p>Same as the video method — one problem, not a list. Note it in a line.</p></div></div><div class=\"step\"><div class=\"n blue\">3</div><div><div class=\"t\">Screenshot just that leak</div><p>Crop tight to the one thing — the broken button, the missing hours, the slow score. Not the whole homepage.</p></div></div><div class=\"step\"><div class=\"n blue\">4</div><div><div class=\"t\">Mark it up</div><p>One circle or arrow, one short caption written on the image. That's the whole markup step.</p></div></div><div class=\"step\"><div class=\"n blue\">5</div><div><div class=\"t\">Write the message</div><p>Hook + reference to the image + the fix in 1-2 sentences + the invite. Use the matching script.</p></div></div><div class=\"step\"><div class=\"n blue\">6</div><div><div class=\"t\">Send & log</div><p>Attach the image, send via their best channel, log it in your tracker exactly like a video send.</p></div></div><div class=\"step\"><div class=\"n blue\">7</div><div><div class=\"t\">Follow up or bridge</div><p>No reply → same 30-day sequence as always. Any reply → move to the phone bridge (Section 07).</p></div></div>\n<div class=\"tint\"><div class=\"eyebrow\">Keep the whole loop under 5 minutes</div>\n<p>Screenshot, one mark, three sentences, send. If you're spending fifteen minutes designing one message, that's a sign to simplify the markup, not polish it further.</p></div>\n</section><section id=\"anatomy\">\n      <div class=\"kick\"><span class=\"num\">Section 04</span>&nbsp;Structure</div>\n      <h2>Anatomy of a visual audit</h2><p class=\"sub\">The four-part structure that gets replies</p>\n<div class=\"beat\"><span class=\"badge tm\">1 sentence</span><div><h4>Hook</h4><p>Name the business, say you were just looking at their site or listing.</p></div></div><div class=\"beat\"><span class=\"badge tm\">the image</span><div><h4>Visual proof</h4><p>The marked-up screenshot — one circle, one caption, one problem.</p></div></div><div class=\"beat\"><span class=\"badge tm\">1-2 sentences</span><div><h4>Solution</h4><p>What your managed system fixes. Outcome first, not the tech behind it.</p></div></div><div class=\"beat\"><span class=\"badge tm\">1 sentence</span><div><h4>Invite</h4><p>A link to your How It Works page, or two specific times to talk.</p></div></div>\n<div class=\"shotcard\"><div class=\"browser\"><div class=\"bar\"><span></span><span></span><span></span></div>\n      <div class=\"body\">[ screenshot of their site / listing goes here ]<br><span class=\"cap\">📍 This is the one leak — circled, captioned in plain words</span></div></div></div>\n<div class=\"soft\"><div class=\"eyebrow\">Do</div><ul style=\"margin:0;\"><li>One circle or arrow — never more than two marks</li><li>A caption in plain words, not marketing language</li><li>Crop tight to the leak, not the whole page</li><li>End with one clear, easy next step</li></ul></div>\n<div class=\"soft\"><div class=\"eyebrow\">Don't</div><ul style=\"margin:0;\"><li>Circle five things — it reads as a teardown</li><li>Send a wall of text under the image</li><li>Use jargon in the caption (\"CRO,\" \"UX\")</li><li>Skip the invite — an image alone asks nothing</li></ul></div>\n<div class=\"tint\"><div class=\"eyebrow\">The frame to hold</div><p class=\"big\">You're not critiquing their business. You're handing them one thing you noticed, for free, because you happen to fix exactly that.</p></div>\n</section><section id=\"scripts\">\n      <div class=\"kick\"><span class=\"num\">Section 05</span>&nbsp;The script library</div>\n      <h2>The script library</h2><p class=\"sub\">13 scenarios, screenshot + message for each</p><div class=\"script\">\n      <span class=\"chip\">Outdated website</span>\n      <div class=\"when\"><b>Screenshot:</b> Their homepage, circle the overall design/date stamp if visible</div>\n      <div class=\"when\"><b>When to use:</b> Site exists but looks dated and isn't converting.</div>\n      <div class=\"say\">Hi — this is Primed &amp; Booked. I was looking at [Business]'s website (screenshot attached) and wanted to flag one thing: the design hasn't been updated in a while, which can make visitors second-guess a business that's actually doing great work. I handle the website, hosting, and follow-up so it's never something you have to think about. Here's a quick look at how the whole thing works: [How It Works link].</div></div><div class=\"script\">\n      <span class=\"chip\">Not mobile-friendly</span>\n      <div class=\"when\"><b>Screenshot:</b> Phone screenshot of their site, circle the broken/overlapping button</div>\n      <div class=\"when\"><b>When to use:</b> Site is broken or clunky on a phone — where most of their traffic is.</div>\n      <div class=\"say\">Quick one for [Business] — I opened your site on my phone (like most of your customers do) and circled the spot where the quote button barely works. That's leads slipping away without you ever seeing them. I rebuild it mobile-first and add automatic follow-up behind it. Here's how it works: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Slow-loading site</span>\n      <div class=\"when\"><b>Screenshot:</b> A speed-test screenshot (e.g. PageSpeed Insights), circle the low score</div>\n      <div class=\"when\"><b>When to use:</b> Page takes several seconds to load.</div>\n      <div class=\"say\">Hey [Business] — ran your site through a quick speed check (attached) and it's loading slower than most visitors will wait for. That's lost jobs you never see happen. I host on fast infrastructure and add missed-call text-back so the leads you do get actually convert. Here's the full picture: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Unclaimed / thin Google Business Profile</span>\n      <div class=\"when\"><b>Screenshot:</b> Their GBP listing, circle missing hours/photos</div>\n      <div class=\"when\"><b>When to use:</b> Profile is missing, unclaimed, or barely filled out.</div>\n      <div class=\"say\">Quick heads-up for [Business] — your Google Business Profile (attached) is missing hours and photos, and that's usually the first place local customers look before they ever reach your site. I'll hand you a step-by-step guide to claim and fix it up yourself in about an hour, alongside the new site, so the two work together instead of one being empty. Here's the full walkthrough: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Few or no reviews</span>\n      <div class=\"when\"><b>Screenshot:</b> Their profile next to a competitor's, circle the review-count gap</div>\n      <div class=\"when\"><b>When to use:</b> Clearly does good work but has under ~10 reviews.</div>\n      <div class=\"say\">Hi [Business] — your work looks solid, but I circled something in the screenshot: you've got a handful of reviews next to competitors sitting at 50+. That gap usually comes down to missed calls and quote requests that never get followed up on — jobs that would've become another five-star review just slip away first. I fix that capture-and-follow-up gap so more of what you're already getting turns into finished work. Here's how: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Call-only, no online booking</span>\n      <div class=\"when\"><b>Screenshot:</b> The contact section, circle 'call only' / no scheduling option</div>\n      <div class=\"when\"><b>When to use:</b> Customers can only reach them by calling and hoping for a callback.</div>\n      <div class=\"say\">Hey — this is Primed &amp; Booked. Right now, booking with [Business] means calling and waiting for a callback (see attached) — and a lot of people won't. I add simple online scheduling tied to your calendar, so they pick a slot in seconds. Here's how it works: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Clunky contact form</span>\n      <div class=\"when\"><b>Screenshot:</b> Their form, circle the field count</div>\n      <div class=\"when\"><b>When to use:</b> Form asks for too much or is buried in the site.</div>\n      <div class=\"say\">Quick one for [Business] — counted the fields on your contact form (attached) and it's asking for more than most people will finish. I replace it with a two-tap quote request that texts you instantly and auto-replies to them. Here's the before-and-after: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">DIY site plateau (Wix/GoDaddy)</span>\n      <div class=\"when\"><b>Screenshot:</b> Their homepage, circle the platform badge/watermark if visible</div>\n      <div class=\"when\"><b>When to use:</b> Owner clearly built it themselves and it's hit a ceiling.</div>\n      <div class=\"say\">Hey [Business] — looks like you built the site yourself, which is more than most owners do. But it's plateaued on turning visitors into quote requests (see attached). I take it off your plate entirely and add the automation behind it. Here's what that looks like: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Great site, no automation</span>\n      <div class=\"when\"><b>Screenshot:</b> Their homepage (looks good), caption noting what's missing — no image circle needed</div>\n      <div class=\"when\"><b>When to use:</b> Polished site but nothing happens after a lead comes in.</div>\n      <div class=\"say\">Your website actually looks great — genuinely nice work. The one thing I didn't see anywhere was automatic follow-up after someone calls and misses you or submits the form. That's where leads quietly die. I add that layer behind the scenes. Here's how it runs: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Running ads, weak landing/follow-up</span>\n      <div class=\"when\"><b>Screenshot:</b> Screenshot of their ad next to their landing page</div>\n      <div class=\"when\"><b>When to use:</b> Spending on Google/Facebook ads but the capture is weak.</div>\n      <div class=\"say\">Hey [Business] — noticed you're running ads (screenshot attached), which means you're paying for every click. But the landing page and follow-up aren't catching those leads, so some of what you paid for is leaking out. I tighten that up and add instant follow-up. Here's the system: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Competitor comparison</span>\n      <div class=\"when\"><b>Screenshot:</b> Two Google listings side by side, circle the gap</div>\n      <div class=\"when\"><b>When to use:</b> A better-marketed competitor is clearly winning locally.</div>\n      <div class=\"say\">Hi [Business] — was comparing a few [trade]s in [city] (attached) and the ones pulling ahead aren't doing better work, they just capture and follow up on leads better. That gap is fixable fast. Here's what closing it would look like: [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Referral-only, ready to scale</span>\n      <div class=\"when\"><b>Screenshot:</b> No screenshot needed — this one is about growth, not a fix</div>\n      <div class=\"when\"><b>When to use:</b> Word-of-mouth business ready to grow beyond referrals.</div>\n      <div class=\"say\">Hey [Business] — looks like you've built a great referral business, which is the hard part. The next step is catching the people who find you online at 9pm searching, where there's currently no net for them. I add the site and automation that turns that traffic into booked jobs. Curious? [link].</div></div><div class=\"script\">\n      <span class=\"chip\">Re-engagement (gone quiet)</span>\n      <div class=\"when\"><b>Screenshot:</b> No new screenshot — reference the one you already sent</div>\n      <div class=\"when\"><b>When to use:</b> A prospect you audited before who never replied.</div>\n      <div class=\"say\">Hey [Business] — circling back on the screenshot I sent a couple weeks ago about [the leak]. Still think it's an easy win. If timing's better now, happy to resend or answer anything directly here — no pressure either way.</div></div><div class=\"tip\"><div class=\"lbl\">Make any script yours</div><p>Swap in one detail only you would know from actually looking — their service area, a specific page, a recent review. That's what separates a real audit from a template that smells like one.</p></div></section><section id=\"channels\">\n      <div class=\"kick\"><span class=\"num\">Section 06</span>&nbsp;Delivery</div>\n      <h2>Channel templates</h2><p class=\"sub\">Email, Messenger, DM, and SMS versions</p>\n<div class=\"card\"><div class=\"eyebrow\">Email</div>\n<p style=\"margin-bottom:4px;\"><b>Subject:</b> Quick thing I noticed on your site</p>\n<p style=\"margin-bottom:10px;font-size:14px;color:var(--muted);\"><b>Alt:</b> One idea for [Business] (2 min)</p>\n<p style=\"font-size:15px;\">Hi [Name],<br><br>I took a quick look at [Business]'s website and marked up one thing that could be costing you quote requests — attached.<br><br>[attached: marked-up screenshot]<br><br>I handle the website, hosting, and follow-up so it's never something you have to think about. Here's a quick look at how the whole system works: [How It Works link]<br><br>— Matt, Primed &amp; Booked</p></div>\n<div class=\"card\"><div class=\"eyebrow\">Facebook Messenger</div>\n<p style=\"font-size:15px;\">Hey [Name]! 👋 Took a look at [Business] and marked up one thing on your site that might be quietly costing you leads (attached). No pitch — thought it'd be useful. Here's how I'd fix it: [link]</p></div>\n<div class=\"card\"><div class=\"eyebrow\">Instagram DM</div>\n<p style=\"font-size:14px;color:var(--muted);margin-bottom:8px;\">Warm up first — like or comment on a recent job photo, then DM the next day.</p>\n<p style=\"font-size:15px;\">Hey! Love the work on your feed 🔥 Marked up one thing on your website that could be costing you quote requests (attached) — no pitch, just thought it'd help. Here's how it works if you're curious: [link]</p></div>\n<div class=\"card\"><div class=\"eyebrow\">SMS <span style=\"font-weight:400;text-transform:none;letter-spacing:0;color:var(--muted);\">— only with a legit business number</span></div>\n<p style=\"font-size:15px;\">Hi [Name] — Primed &amp; Booked here. Marked up one quick thing on [Business]'s site that's likely costing you leads. Sending the image now — worth a look?</p></div>\n<div class=\"tip\"><div class=\"lbl\">Channel etiquette</div><p>Same rule as always: one message, one image, zero pressure. Match each channel's tone — email a touch fuller, DMs casual, SMS reserved for warmer prospects.</p></div>\n</section><section id=\"bridge\">\n      <div class=\"kick\"><span class=\"num\">Section 07</span>&nbsp;The bridge</div>\n      <h2>Bridging to the call</h2><p class=\"sub\">Turning a reply into a booked time</p>\n<div class=\"step\"><div class=\"n blue\">1</div><div><div class=\"t\">Watch for the signal</div><p>Any reply that isn't a flat no counts: a question, \"how much,\" \"interesting,\" \"send more info.\" That's your green light — they're engaged.</p></div></div><div class=\"step\"><div class=\"n blue\">2</div><div><div class=\"t\">Don't say \"let's hop on a call\"</div><p>Too vague, too easy to leave unanswered. It puts the work of deciding on them.</p></div></div><div class=\"step\"><div class=\"n blue\">3</div><div><div class=\"t\">Offer two specific windows</div><p>\"I've got Tuesday 10am or Thursday 2pm — either work?\" A concrete choice gets a yes far more often than an open question.</p></div></div><div class=\"step\"><div class=\"n blue\">4</div><div><div class=\"t\">If they keep replying in writing, let them</div><p>Some people will ask two or three questions by text and then say \"ok let's do it\" without ever getting on the phone. That's a full win — don't force a call that isn't needed.</p></div></div><div class=\"step\"><div class=\"n blue\">5</div><div><div class=\"t\">Confirm it</div><p>Once they pick a time, send a one-line confirmation the day before. It's a small thing that quietly cuts no-shows a lot.</p></div></div>\n<div class=\"tint\"><div class=\"eyebrow\">The reframe that matters most</div>\n<p class=\"big\">By the time you're bridging to a call, the hard part is already done. They reached out to you. You're not pitching a stranger — you're confirming details with someone who already said yes to a conversation.</p></div>\n<div class=\"card\"><h4>Reply templates once they respond</h4>\n<p style=\"margin:0 0 8px;\"><b>They ask a question:</b> answer it in 1-2 sentences, then: \"Happy to walk through the rest live too — I've got Tuesday 10am or Thursday 2pm, either work?\"</p>\n<p style=\"margin:0 0 8px;\"><b>They say \"how much\":</b> \"$1,500 to set up and $297 a month, everything included: the text-back, instant replies, booking, follow-up, and me running it. Works with your current website, no contract. Want me to walk through what it'd look like for you — Tuesday 10am or Thursday 2pm?\"</p>\n<p style=\"margin:0;\"><b>They say \"send more info\":</b> send the How It Works link, then: \"That covers the how — want to grab 20 minutes so I can answer anything specific to your business? Tuesday 10am or Thursday 2pm both work on my end.\"</p></div>\n<div class=\"tip\"><div class=\"lbl\">If two windows don't land</div><p>\"No worries — what does work for you sometime this week?\" keeps it moving without you having to guess again.</p></div>\n</section><section id=\"oncall\">\n      <div class=\"kick\"><span class=\"num\">Section 08</span>&nbsp;On the call</div>\n      <h2>On the call</h2><p class=\"sub\">A low-pressure structure, so it's never a blank page</p>\n<div class=\"callscript\"><div class=\"callscript cs-row\"><span class=\"cs-n\">1</span><div><div class=\"cs-t\">Open warm</div><p>Thank them for the time, reference the specific thing you flagged: \"Thanks for making time — I know I mentioned the mobile quote form earlier.\"</p></div></div><div class=\"callscript cs-row\"><span class=\"cs-n\">2</span><div><div class=\"cs-t\">Ask permission</div><p>\"Mind if I ask a couple quick questions about how you handle leads right now?\" — this hands you the floor without it feeling like an interrogation.</p></div></div><div class=\"callscript cs-row\"><span class=\"cs-n\">3</span><div><div class=\"cs-t\">Two simple questions</div><p>\"How are you currently handling missed calls or quote requests?\" and \"Roughly how many leads would you say you get a month?\" Their answers do most of your selling for you.</p></div></div><div class=\"callscript cs-row\"><span class=\"cs-n\">4</span><div><div class=\"cs-t\">Present the fix in plain terms</div><p>One or two sentences, using their own words back: \"So right now if you miss a call it's just gone — I'd have that person get an instant text instead, and automatic follow-up after.\"</p></div></div><div class=\"callscript cs-row\"><span class=\"cs-n\">5</span><div><div class=\"cs-t\">Say the price plainly</div><p>\"$1,500 to set everything up, then $297 a month, everything included, no contract.\" Say it once, then stop talking. (Only if they truly just need a website: the $950 one-time Starter Site.)</p></div></div><div class=\"callscript cs-row\"><span class=\"cs-n\">6</span><div><div class=\"cs-t\">Ask, don't push</div><p>\"Want me to get started, or would a written quote be easier to look over first?\" Either answer is a good outcome.</p></div></div></div>\n<div class=\"tip\"><div class=\"lbl\">If your mind goes blank</div>\n<p>Keep this page open during the call — there's nothing wrong with glancing at notes. \"Let me just check something\" is a completely normal thing to say and buys you a breath. Pauses are fine; they read as thoughtful, not unprepared.</p></div>\n<div class=\"soft\"><div class=\"eyebrow\">Why this call is lower-pressure than it feels</div>\n<ul style=\"margin:0;\"><li>They already said yes to talking — you're not cold-pitching</li><li>You already know their one leak — you're not guessing what to say</li><li>You have a script in front of you — you're never starting from a blank page</li><li>A \"no\" here just means back to the follow-up sequence, not the end of anything</li></ul></div>\n</section><section id=\"followup\">\n      <div class=\"kick\"><span class=\"num\">Section 09</span>&nbsp;Persistence</div>\n      <h2>Follow-up sequence</h2><p class=\"sub\">The 30-day cadence, adapted for this method</p>\n<div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 0</span><span class=\"badge\">Screenshot</span></div><p style=\"color:var(--ink);\"><b>The original.</b> Marked-up screenshot + short note.</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 3</span><span class=\"badge\">Same channel</span></div><p style=\"color:var(--ink);\"><b>Gentle bump.</b> \"Just making sure that came through — no worries if now's not the time.\"</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 7</span><span class=\"badge\">Same / email</span></div><p style=\"color:var(--ink);\"><b>Add value.</b> \"Curious what you thought — here's a quick example of it working for a similar [trade].\"</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 14</span><span class=\"badge\">Email</span></div><p style=\"color:var(--ink);\"><b>New angle.</b> A different leak, freshly screenshotted. \"Noticed something else that might be a bigger win.\"</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 21</span><span class=\"badge\">Email</span></div><p style=\"color:var(--ink);\"><b>Soft proof.</b> A short case study or testimonial. Low ask.</p></div><div class=\"drow\"><div class=\"top\"><span class=\"nm\">Day 30</span><span class=\"badge\">Email / DM</span></div><p style=\"color:var(--ink);\"><b>Close the loop.</b> \"I'll stop reaching out after this — but if it's ever on your list, I'm one message away.\"</p></div>\n<div class=\"tint\"><div class=\"eyebrow\">Same rules as always</div><ul style=\"margin:0;\"><li>Every touch adds something new — never just \"bumping this\"</li><li>Stop the instant they reply or book</li><li>The day-30 close stays warm, never guilt-driven</li></ul></div>\n</section><section id=\"objections\">\n      <div class=\"kick\"><span class=\"num\">Section 10</span>&nbsp;Objections</div>\n      <h2>Objection handling</h2><p class=\"sub\">What's different in writing, plus the same eight</p>\n<h3 class=\"blk\">What's different in writing</h3>\n<div class=\"card\"><h4 style=\"color:var(--blue);\">\"Is this some kind of scam? / How'd you get this screenshot?\"</h4><p style=\"margin-top:5px;font-size:15.5px;\">\"Totally fair to ask — I just pulled it from your public website, the same way any visitor would see it. I do this for [trade]s as part of what I do at Primed &amp; Booked. Happy to hop on a quick call so it's less 'random message' and more a real conversation.\"</p></div><div class=\"card\"><h4 style=\"color:var(--blue);\">\"Just send me a quote\"</h4><p style=\"margin-top:5px;font-size:15.5px;\">\"Happy to. It's $1,500 to set up and $297/month, everything included, no contract, and it works with the website you already have. I'll send the details now. If anything's unclear once you read it, just ask.\"</p></div>\n<h3 class=\"blk\">Everything else is the same</h3>\n<div class=\"soft\"><div class=\"eyebrow\">The same eight, word for word</div><p style=\"margin-bottom:8px;\">Once you're on a call, every objection works exactly like the video method — swap \"the video\" for \"the screenshot I sent\" and the same answers hold:</p>\n<ul style=\"margin:0;\"><li>We're too busy right now</li><li>We already have a website</li><li>It's too expensive</li><li>I tried something like this before and it didn't work</li><li>I can do it myself</li><li>I need to think about it / talk to my partner</li><li>I'm locked into a contract with someone else</li><li>It's my slow season, let's talk later</li></ul></div>\n<div class=\"tint\"><div class=\"eyebrow\">The universal move</div><p class=\"big\">Agree → reframe → re-ask, smaller. That doesn't change based on how you first reached them.</p></div>\n</section><section id=\"checklist\">\n      <div class=\"kick\"><span class=\"num\">Section 11</span>&nbsp;Daily ops</div>\n      <h2>Daily checklist</h2><p class=\"sub\">Print it. Run it. No camera required.</p>\n<div class=\"chkbar\"><button id=\"chk-reset-va\" type=\"button\">↻ Reset day</button></div>\n<div class=\"grouplbl\">Find & screenshot</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Pull today's pre-scored prospect list</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Open each site; find <b>one leak</b> per prospect</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Screenshot just that leak — cropped tight</div></div>\n<div class=\"grouplbl\">Mark up & write</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">One circle or arrow, one plain-language caption</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Write the message using the matching script</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Read it back once before sending</div></div>\n<div class=\"grouplbl\">Send & log</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Send via best channel (email / DM / SMS)</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Log every send in the tracker with leak + date</div></div>\n<div class=\"grouplbl\">Follow up & bridge</div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Work the queue: day 3, 7, 14, 21, 30 touches</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Any reply → offer two specific call times</div></div>\n<div class=\"chk\"><div class=\"box\"></div><div class=\"tx\">Confirm booked calls the day before</div></div>\n<div class=\"tip\" style=\"margin-top:16px;\"><div class=\"lbl\">Daily minimum</div><p>10 sent · queue cleared · any replies bridged toward a time. No camera required for any of it.</p></div>\n</section><section id=\"combine\">\n      <div class=\"kick\"><span class=\"num\">Section 12</span>&nbsp;Wrap-up</div>\n      <h2>Combining both methods</h2><p class=\"sub\">When to use this vs. the video</p>\n<p>Both methods point at the same one thing — a leak worth fixing — they just arrive differently. Neither is the \"real\" one.</p>\n<div class=\"grid2\" style=\"display:flex;gap:11px;\">\n<div class=\"card\" style=\"flex:1;\"><h4>Use the visual audit when...</h4><p>It's your default. Lower pressure, fully reviewable, sustainable at 10/day without dreading the recording block.</p></div>\n<div class=\"card\" style=\"flex:1;\"><h4>Use video when...</h4><p>You're feeling up for it, or a prospect is warm enough that the extra effort clearly earns its keep — never as an obligation.</p></div>\n</div>\n<div class=\"tint\"><div class=\"eyebrow\">The only rule that matters</div><p class=\"big\">Pick whichever one you'll actually send ten of today. Consistency beats format every time.</p></div>\n</section>\n</div>\n<div class=\"foot\">\n  <p class=\"big\">Show them the one thing that's costing them jobs. Say it plainly. Point to how it works. Let them come to you.</p>\n  <div class=\"sm\">Primed &amp; Booked · Visual Audit Playbook · v1.0</div>\n  <a class=\"totop\" href=\"#contents\">↑ Back to contents</a>\n</div>";
